// Out-of-line method definitions: ClassName::method(...) — the only
// method shape the regex extractor captures.
shapes::Circle::Circle(double radius) : radius_(radius) {}

double shapes::Circle::area() const {
    return 3.14159 * radius_ * radius_;
}

double shapes::Circle::circumference() const {
    return 2.0 * 3.14159 * radius_;
}

double distance(const shapes::Point& a, const shapes::Point& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}

class Circle(Shape):
    """A circle shape that reuses area_of."""

    def __init__(self, radius: float) -> None:
        super().__init__("circle")
        self.radius = radius

    def area(self) -> float:
        """Compute this circle's area via the module helper."""
        return area_of(self.radius)

    def scaled(self, factor: float) -> "Circle":
        """Return a new Circle scaled by factor, using a nested helper."""

        def clamp(value: float) -> float:
            """Nested function: never return a negative scale."""
            return value if value > 0 else 0.0

        return Circle(self.radius * clamp(factor))

class Shape:
    """Base shape with a name and an abstract-ish area hook."""

    def __init__(self, name: str) -> None:
        self.name = name

    def describe(self) -> str:
        """Return a human label for this shape."""
        return f"shape:{self.name}"
